// Hidden suite for T05, written from the spec before the implementation.
import { describe, expect, it } from "vitest";
import { planDelivery } from "../src/quiet-hours.ts";
import type { DeliveryPrefs, Notice } from "../src/quiet-hours.ts";

const NOW = { deferred: false, deliverIn: 0 };
const held = (deliverIn: number) => ({ deferred: true, deliverIn });
const DAYTIME: DeliveryPrefs = { quiet: { start: 60, end: 120 }, bypass: ["pager"] };
const OVERNIGHT: DeliveryPrefs = { quiet: { start: 1320, end: 420 }, bypass: ["pager"] };
const PLAIN: Notice = { senderId: "news", urgent: false };

describe("planDelivery: windows", () => {
  it("delivers immediately without quiet hours", () => {
    expect(planDelivery({ quiet: null, bypass: [] }, PLAIN, 600)).toEqual(NOW);
  });

  it("delivers immediately outside quiet hours", () => {
    expect(planDelivery(DAYTIME, PLAIN, 30)).toEqual(NOW);
    expect(planDelivery(DAYTIME, PLAIN, 120)).toEqual(NOW);
  });

  it("holds a notice at the first minute of a same-day window", () => {
    expect(planDelivery(DAYTIME, PLAIN, 60)).toEqual(held(60));
  });

  it("holds a notice until the end of a same-day window", () => {
    expect(planDelivery(DAYTIME, PLAIN, 90)).toEqual(held(30));
    expect(planDelivery(DAYTIME, PLAIN, 119)).toEqual(held(1));
  });

  it("holds a notice at the first minute of an overnight window", () => {
    expect(planDelivery(OVERNIGHT, PLAIN, 1320)).toEqual(held(540));
  });

  it("matches the documented overnight example", () => {
    expect(planDelivery(OVERNIGHT, PLAIN, 1380)).toEqual(held(480));
    expect(planDelivery(OVERNIGHT, PLAIN, 0)).toEqual(held(420));
    expect(planDelivery(OVERNIGHT, PLAIN, 419)).toEqual(held(1));
    expect(planDelivery(OVERNIGHT, PLAIN, 420)).toEqual(NOW);
    expect(planDelivery(OVERNIGHT, PLAIN, 1319)).toEqual(NOW);
  });

  it("treats equal start and end as no quiet period", () => {
    const prefs: DeliveryPrefs = { quiet: { start: 300, end: 300 }, bypass: [] };
    expect(planDelivery(prefs, PLAIN, 300)).toEqual(NOW);
    expect(planDelivery(prefs, PLAIN, 10)).toEqual(NOW);
  });
});

describe("planDelivery: bypass", () => {
  it("delivers urgent notices from bypass senders immediately", () => {
    expect(planDelivery(OVERNIGHT, { senderId: "pager", urgent: true }, 1380)).toEqual(NOW);
  });

  it("holds non-urgent notices from bypass senders", () => {
    expect(planDelivery(OVERNIGHT, { senderId: "pager", urgent: false }, 1380)).toEqual(held(480));
  });

  it("holds urgent notices from other senders", () => {
    expect(planDelivery(OVERNIGHT, { senderId: "news", urgent: true }, 1380)).toEqual(held(480));
  });
});

describe("planDelivery: validation", () => {
  it("rejects an invalid current minute", () => {
    expect(() => planDelivery(DAYTIME, PLAIN, -1)).toThrow(RangeError);
    expect(() => planDelivery(DAYTIME, PLAIN, 1440)).toThrow(RangeError);
    expect(() => planDelivery({ quiet: null, bypass: [] }, PLAIN, 12.5)).toThrow(RangeError);
  });

  it("rejects a quiet start outside the day", () => {
    expect(() => planDelivery({ quiet: { start: 1440, end: 60 }, bypass: [] }, PLAIN, 30)).toThrow(RangeError);
  });

  it("rejects a quiet end outside the day", () => {
    expect(() => planDelivery({ quiet: { start: 60, end: 1440 }, bypass: [] }, PLAIN, 30)).toThrow(RangeError);
  });
});
